pub fn written(site: Site, old: &Old, new: &mut Build, at: Node, cx: &mut Context) -> Result<(), Halt> {
    match site.patch() {
        1 => match site.index() {
            0 => p0001::stands(old, new, at, cx),
            _ => Err(Halt::NoSite(site)),
        },
        5 => match site.index() {
            0 => p0005::landing_state_branch(old, new, at, cx),
            _ => Err(Halt::NoSite(site)),
        },
        7 => match site.index() {
            0 => p0007::landing_state_members(old, new, at, cx),
            _ => Err(Halt::NoSite(site)),
        },
        _ => Err(Halt::NoSite(site)),
    }
}

